    MintTownyEspionage espionage;EspionageService service;EspionageRepository core;IntelController intel;IntelRepository archive;EspionageMenuManager menus;Town target;UUID firstReport;long sampled;final Set<UUID> revoked=new HashSet<>();CountDownLatch disk;
