    void corruptChecks()throws Exception{check(espionage.isEnabled()&&Bukkit.getPluginManager().getPlugin("NeverLandTownyBuilds").isEnabled()&&!intel.available()&&!archive.readable(),"corrupt optional archive leaves espionage core and other addon enabled");check(core.operation(WAITING).status()==OperationStatus.ACTIVE&&core.operation(WAITING).cost()==999&&core.reports(T).size()==4,"corrupt archive does not fail accepted missions delete reports or change cost");check(!service.forceComplete(WAITING)&&service.start(mayor,target,service.registry().get("treasury")).status()==EspionageService.StartStatus.STORAGE_BUSY,"corrupt optional file neutral-pauses completion and new debit before bank");check(Files.readString(espionage.getDataFolder().toPath().resolve("intelligence.yml")).equals("schema: 99\nreceipts: damaged fixture\n"),"damaged optional file preserved for recovery");menus.openReports(mayor);check(windows.get(M).getItem(0)!=null,"original saved reports still accessible without optional archive");finishProbe();}
    @SuppressWarnings("unchecked")CountDownLatch lock(String name)throws Exception{var type=Class.forName("ru.neverland.core.AtomicFiles",true,espionage.getClass().getClassLoader());var f=type.getDeclaredField("writers");f.setAccessible(true);var locks=(Map<Path,ReentrantLock>)f.get(null);var file=espionage.getDataFolder().toPath().resolve(name).toAbsolutePath().normalize();var lock=locks.computeIfAbsent(file,key->new ReentrantLock());var release=new CountDownLatch(1);var started=new CountDownLatch(1);var thread=new Thread(()->{lock.lock();started.countDown();try{release.await(15,TimeUnit.SECONDS);}catch(InterruptedException error){Thread.currentThread().interrupt();}finally{lock.unlock();}},"espionage-probe-delay");thread.setDaemon(true);thread.start();if(!started.await(1,TimeUnit.SECONDS))throw new AssertionError("physical file lock unavailable");return release;}
